import Foundation
import Testing
@testable import DriverrCore

@Suite("SSHHostKey")
struct SSHHostKeyTests {
  /// Generated by OpenSSH, so the test does not depend on this machine's keys:
  ///   ssh-keygen -t ed25519 -N '' -f k && ssh-keygen -lf k.pub
  static let blobBase64 =
    "AAAAC3NzaC1lZDI1NTE5AAAAIHQscScbaDTwbjda84QJbQJ6JINzLznyKKnhfh6LIWak"
  static let expectedFingerprint = "SHA256:3ZVlu7DWz3ouUzrF93cx5zY5jkgAbT4R9WQqqZJePA8"

  private func makeKey() -> SSHHostKey {
    SSHHostKey(
      algorithm: "ssh-ed25519",
      blob: Data(base64Encoded: Self.blobBase64)!
    )
  }

  @Test("fingerprint matches what ssh-keygen -lf prints for the same key")
  func fingerprintMatchesOpenSSH() {
    #expect(makeKey().fingerprint == Self.expectedFingerprint)
  }

  @Test("fingerprint drops base64 padding, as OpenSSH does")
  func fingerprintHasNoPadding() {
    #expect(!makeKey().fingerprint.contains("="))
  }

  @Test("two keys with the same blob are equal regardless of comment")
  func equalityIsByBlob() {
    #expect(makeKey() == makeKey())
  }
}

@Suite("SSHAuthMethod")
struct SSHAuthMethodTests {
  @Test("a password never appears in the debug description")
  func passwordIsRedacted() {
    let method = SSHAuthMethod.password("hunter2")
    #expect(!String(describing: method).contains("hunter2"))
    #expect(!method.debugDescription.contains("hunter2"))
  }

  @Test("a private key's bytes never appear in the debug description")
  func privateKeyIsRedacted() {
    let key = SSHPrivateKey(rawRepresentation: Data(repeating: 0xAB, count: 32))
    let method = SSHAuthMethod.privateKey(key)
    #expect(!method.debugDescription.contains("AB"))
    #expect(!String(describing: key).contains("AB"))
  }

  @Test("debug description still identifies which method it is")
  func debugDescriptionNamesTheMethod() {
    let key = SSHPrivateKey(rawRepresentation: Data(repeating: 1, count: 32))
    #expect(SSHAuthMethod.password("x").debugDescription.contains("password"))
    #expect(SSHAuthMethod.privateKey(key).debugDescription.contains("privateKey"))
  }
}
